import { existsSync, readFileSync, writeFileSync } from 'node:fs';

// Register the flaxia:// scheme for the native sign-in return. The platform
// projects are generated by `cap sync`, so this runs after that step and is a
// no-op when a platform is not present.

const SCHEME = 'flaxia';
const HOST = 'auth';

const androidManifest = 'android/app/src/main/AndroidManifest.xml';
if (existsSync(androidManifest)) {
  const source = readFileSync(androidManifest, 'utf8');
  if (!source.includes(`android:scheme="${SCHEME}"`)) {
    const filter = `
            <intent-filter android:autoVerify="false">
                <action android:name="android.intent.action.VIEW" />
                <category android:name="android.intent.category.DEFAULT" />
                <category android:name="android.intent.category.BROWSABLE" />
                <data android:scheme="${SCHEME}" android:host="${HOST}" />
            </intent-filter>`;
    const pattern = /(<activity\b[^>]*android:name="\.MainActivity"[\s\S]*?)(<\/activity>)/;
    if (!pattern.test(source)) throw new Error('MainActivity not found in AndroidManifest.xml');
    writeFileSync(androidManifest, source.replace(pattern, `$1${filter}$2`));
    console.log(`Registered ${SCHEME}:// scheme on Android`);
  }
}

const iosInfo = 'ios/App/App/Info.plist';
if (existsSync(iosInfo)) {
  const source = readFileSync(iosInfo, 'utf8');
  if (!source.includes(`<string>${SCHEME}</string>`)) {
    const entry = `\t<key>CFBundleURLTypes</key>
\t<array>
\t\t<dict>
\t\t\t<key>CFBundleURLName</key>
\t\t\t<string>app.flaxia.auth</string>
\t\t\t<key>CFBundleURLSchemes</key>
\t\t\t<array>
\t\t\t\t<string>${SCHEME}</string>
\t\t\t</array>
\t\t</dict>
\t</array>
`;
    if (!source.includes('</dict>\n</plist>')) throw new Error('Info.plist root dict not found');
    writeFileSync(iosInfo, source.replace('</dict>\n</plist>', `${entry}</dict>\n</plist>`));
    console.log(`Registered ${SCHEME}:// scheme on iOS`);
  }
}
